const time=value=>typeof value==="string" && value.endsWith("Z") ? Date.parse(value) : NaN;
const thai=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Bangkok",dateStyle:"short",timeStyle:"short"});
return $input.all().map(({json},index)=>{
  const {asOf,calendar,beforeMinutes,afterMinutes}=json;
  const now=time(asOf), start=time(calendar?.validFrom), end=time(calendar?.validUntil);
  const margins=[beforeMinutes,afterMinutes];
  const bufferValid=margins.every(value=>Number.isSafeInteger(value)&&value>=0);
  const before=beforeMinutes*60000, after=afterMinutes*60000;
  const events=Array.isArray(calendar?.events)?calendar.events:null;
  const valid=bufferValid && typeof calendar?.source==="string" && calendar.source.trim() &&
    Number.isFinite(now) && Number.isFinite(start) && Number.isFinite(end) && start<end &&
    start<=now-after && now+before<end && events &&
    events.every(event=>event && typeof event.title==="string" && event.title.trim() &&
      /^[A-Z]{3}$/.test(event.currency) && ["HIGH","MEDIUM","LOW"].includes(event.impact) &&
      time(event.scheduledAt)>=start && time(event.scheduledAt)<end);
  const relevant=valid?events.filter(event=>event.currency==="USD"&&event.impact==="HIGH")
    .sort((a,b)=>time(a.scheduledAt)-time(b.scheduledAt)):[];
  const present=event=>({title:event.title,scheduledAt:event.scheduledAt,
    bangkokTime:thai.format(time(event.scheduledAt)),timeZone:"Asia/Bangkok"});
  const active=relevant.filter(event=>time(event.scheduledAt)-before<=now&&now<=time(event.scheduledAt)+after);
  const next=relevant.find(event=>time(event.scheduledAt)>now);
  const status=!valid?"NEWS_CALENDAR_UNAVAILABLE":active.length?"HIGH_NEWS_RISK":"CLEAR";
  return {json:{asOf,newsRisk:{status,source:calendar?.source??null,
    canProceedToSignalChecks:status==="CLEAR",activeEvents:active.map(present),nextEvent:next?present(next):null}},
    pairedItem:{item:index}};
});
